import { readFileSync, writeFileSync } from 'node:fs';

const SOURCES = [
  { path: 'a.txt', label: 'Alpha' },
  { path: 'b.txt', label: 'Beta' },
  { path: 'c.txt', label: 'Gamma' },
];

const parsed = SOURCES.map(({ path, label }) => {
  const raw = readFileSync(path, 'utf8');
  const m = raw.match(/^([A-Za-z]+) population:\s*(\d+)\s*$/);
  if (!m) throw new Error(`${path}: unexpected format ${JSON.stringify(raw)}`);
  if (m[1] !== label) throw new Error(`${path}: label ${m[1]} != expected ${label}`);
  return { path, label: m[1], population: Number(m[2]) };
});

const total = parsed.reduce((sum, s) => sum + s.population, 0);
if (!Number.isFinite(total) || !Number.isInteger(total)) throw new Error('non-integer total');
if (parsed.some((s) => !Number.isInteger(s.population) || s.population < 0)) {
  throw new Error('invalid population');
}

writeFileSync('answer.json', JSON.stringify({ total }, null, 2) + '\n');

// Re-read the written artifact and cross-check it against the sources.
const answer = JSON.parse(readFileSync('answer.json', 'utf8'));
if (answer.total !== total) throw new Error(`answer.json total ${answer.total} != computed ${total}`);
if (typeof answer.total !== 'number') throw new Error('total is not numeric');
if (Object.keys(answer).join(',') !== 'total') throw new Error('unexpected keys: ' + Object.keys(answer).join(','));

for (const s of parsed) console.log(`${s.path}: ${s.label} population = ${s.population}`);
console.log(`sum = ${total}`);
console.log('answer.json =', JSON.stringify(answer));
console.log('SELF-CHECK OK');

